#include <libgen.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string>

#include <magic.h>

struct Environment {
  Environment(std::string data_dir) {
    magic = magic_open(MAGIC_COMPRESS|MAGIC_CONTINUE);
    std::string magic_path = data_dir + "/magic";
    if (magic_load(magic, magic_path.c_str())) {
      fprintf(stderr, "error loading magic file: %s\n", magic_error(magic));
      exit(1);
    }
  }

  magic_t magic;
};

static Environment* env;

extern "C" int LLVMFuzzerInitialize(int* argc, char*** argv) {
  char* exe_path = (*argv)[0];
  // dirname() can modify its argument.
  char* exe_path_copy = strdup(exe_path);
  char* dir = dirname(exe_path_copy);
  env = new Environment(dir);
  free(exe_path_copy);
  return 0;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
  if (size < 1)
    return 0;
  magic_buffer(env->magic, data, size);
  return 0;
}
---

autoreconf -i
./configure --enable-static
make V=1 all
$CXX $CXXFLAGS -std=c++11 -Isrc/      $SRC/magic_fuzzer.cc -o $OUT/magic_fuzzer      $LIB_FUZZING_ENGINE ./src/.libs/libmagic.a -l:libz.a
$CXX $CXXFLAGS -std=c++11 -Isrc/      $SRC/magic_fuzzer_loaddb.cc -o $OUT/magic_fuzzer_loaddb      $LIB_FUZZING_ENGINE ./src/.libs/libmagic.a -l:libz.a
cp ./magic/magic.mgc $OUT/
mkdir pocs_all
find $SRC/pocs/ -type f -print0 | xargs -0 -I % mv -f % ./pocs_all
zip -j $OUT/magic_fuzzer_seed_corpus.zip ./tests/*.testfile $SRC/binary-samples/{elf,pe}-* $SRC/pocs_all
